    #[test]
    fn compute_skips_run_anyway() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let mut skip = HashSet::new();
        skip.insert("a".to_string());

        let skipped = graph.compute_skips(&skip, SkipBehavior::RunAnyway);

        assert!(skipped.is_empty());
    }

    // ---- Circular reference / infinite loop tests ----

    #[test]
    fn transitive_dependents_does_not_loop_on_two_node_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        // Must terminate, not infinite loop
        let deps = graph.transitive_dependents("a");
        assert!(deps.contains("b"));
    }

    #[test]
    fn transitive_dependents_does_not_loop_on_three_node_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["c".to_string()])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["b".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        assert!(deps.contains("b"));
        assert!(deps.contains("c"));
    }

    #[test]
    fn transitive_dependents_does_not_loop_on_self_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["a".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        // "a" depends on itself, so it is its own transitive dependent
        assert!(deps.contains("a"));
    }

    #[test]
    fn compute_skips_does_not_loop_on_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["a".to_string()])
            .build()
            .unwrap();

        let mut skip = HashSet::new();
        skip.insert("a".to_string());

        // Must terminate even though a <-> b form a cycle
        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
        assert!(skipped.contains("a"));
        assert!(skipped.contains("b"));
        assert!(skipped.contains("c"));
    }

    #[test]
    fn topo_sort_detects_self_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["a".to_string()])
            .build()
            .unwrap();

        let result = graph.topological_order();
        assert!(result.is_err());
    }

    #[test]
    fn topo_sort_detects_three_node_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["c".to_string()])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["b".to_string()])
            .build()
            .unwrap();

        let result = graph.topological_order();
        assert!(result.is_err());
    }

    #[test]
    fn topo_sort_cycle_error_contains_involved_steps() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let err = graph.topological_order().unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("a"));
        assert!(msg.contains("b"));
    }

    #[test]
    fn topo_sort_cycle_in_subgraph_with_acyclic_part() {
        // "x" is acyclic, but "a" <-> "b" form a cycle
        let graph = DependencyGraph::builder()
            .add_step("x", vec![])
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let result = graph.topological_order();
        assert!(result.is_err());
    }

    #[test]
    fn find_cycle_in_subgraph_with_acyclic_part() {
        let graph = DependencyGraph::builder()
            .add_step("x", vec![])
            .add_step("y", vec!["x".to_string()])
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let cycle = graph.find_cycle();
        assert!(cycle.is_some());
        let path = cycle.unwrap();
        // Cycle must involve "a" and "b", not "x" or "y"
        assert!(path.contains(&"a".to_string()));
        assert!(path.contains(&"b".to_string()));
    }

    #[test]
    fn find_cycle_returns_path_starting_and_ending_same_node() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["c".to_string()])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["b".to_string()])
            .build()
            .unwrap();

        let cycle = graph.find_cycle().unwrap();
        assert_eq!(cycle.first(), cycle.last());
    }

    #[test]
    fn parallel_groups_errors_on_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let result = graph.parallel_groups();
        assert!(result.is_err());
    }

    #[test]
    fn parallel_groups_errors_on_self_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["a".to_string()])
            .build()
            .unwrap();

        let result = graph.parallel_groups();
        assert!(result.is_err());
    }

    // ---- Builder edge cases ----

    #[test]
    fn builder_merges_dependencies_for_duplicate_step() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec![])
            .add_step("c", vec!["a".to_string()])
            .add_step("c", vec!["b".to_string()])
            .build()
            .unwrap();

        let deps = graph.dependencies_of("c").unwrap();
        assert!(deps.contains("a"));
        assert!(deps.contains("b"));
    }

    #[test]
    fn builder_error_message_names_both_steps() {
        let result = DependencyGraph::builder()
            .add_step("deploy", vec!["ghost".to_string()])
            .build();

        let err = result.unwrap_err();
        let msg = err.to_string();
        assert!(msg.contains("deploy"));
        assert!(msg.contains("ghost"));
    }

    // ---- Query edge cases ----

    #[test]
    fn dependencies_of_unknown_step_returns_none() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .build()
            .unwrap();

        assert!(graph.dependencies_of("nonexistent").is_none());
    }

    #[test]
    fn dependents_of_unknown_step_returns_none() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .build()
            .unwrap();

        assert!(graph.dependents_of("nonexistent").is_none());
    }

    #[test]
    fn contains_returns_false_for_unknown_step() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .build()
            .unwrap();

        assert!(!graph.contains("nonexistent"));
    }

    #[test]
    fn transitive_dependents_of_unknown_step_is_empty() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .build()
            .unwrap();

        assert!(graph.transitive_dependents("nonexistent").is_empty());
    }

    #[test]
    fn is_ready_returns_true_for_unknown_step() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .build()
            .unwrap();

        // Unknown step has no recorded deps, so is_ready returns true
        assert!(graph.is_ready("nonexistent", &HashSet::new()));
    }

    // ---- Disconnected components ----

    #[test]
    fn topo_sort_disconnected_components() {
        let graph = DependencyGraph::builder()
            .add_step("a1", vec![])
            .add_step("a2", vec!["a1".to_string()])
            .add_step("b1", vec![])
            .add_step("b2", vec!["b1".to_string()])
            .build()
            .unwrap();

        let order = graph.topological_order().unwrap();
        assert_eq!(order.len(), 4);

        let a1 = order.iter().position(|s| s == "a1").unwrap();
        let a2 = order.iter().position(|s| s == "a2").unwrap();
        let b1 = order.iter().position(|s| s == "b1").unwrap();
        let b2 = order.iter().position(|s| s == "b2").unwrap();

        assert!(a1 < a2);
        assert!(b1 < b2);
    }

    #[test]
    fn parallel_groups_disconnected_components() {
        let graph = DependencyGraph::builder()
            .add_step("a1", vec![])
            .add_step("a2", vec!["a1".to_string()])
            .add_step("b1", vec![])
            .add_step("b2", vec!["b1".to_string()])
            .build()
            .unwrap();

        let groups = graph.parallel_groups().unwrap();
        // Group 1: [a1, b1], Group 2: [a2, b2]
        assert_eq!(groups.len(), 2);
        assert_eq!(groups[0].len(), 2);
        assert_eq!(groups[1].len(), 2);
    }

    // ---- Fan-in / fan-out ----

    #[test]
    fn parallel_groups_fan_out() {
        let graph = DependencyGraph::builder()
            .add_step("root", vec![])
            .add_step("a", vec!["root".to_string()])
            .add_step("b", vec!["root".to_string()])
            .add_step("c", vec!["root".to_string()])
            .build()
            .unwrap();

        let groups = graph.parallel_groups().unwrap();
        assert_eq!(groups.len(), 2);
        assert_eq!(groups[0], vec!["root"]);
        assert_eq!(groups[1].len(), 3);
    }

    #[test]
    fn parallel_groups_fan_in() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec![])
            .add_step("c", vec![])
            .add_step("final", vec![
                "a".to_string(),
                "b".to_string(),
                "c".to_string(),
            ])
            .build()
            .unwrap();

        let groups = graph.parallel_groups().unwrap();
        assert_eq!(groups.len(), 2);
        assert_eq!(groups[0].len(), 3);
        assert_eq!(groups[1], vec!["final"]);
    }

    // ---- Complex transitive dependents ----

    #[test]
    fn transitive_dependents_diamond() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["a".to_string()])
            .add_step("d", vec!["b".to_string(), "c".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        assert_eq!(deps.len(), 3);
        assert!(deps.contains("b"));
        assert!(deps.contains("c"));
        assert!(deps.contains("d"));
    }

    #[test]
    fn transitive_dependents_does_not_include_self() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        assert!(!deps.contains("a"));
    }

    // ---- is_ready with partial completion ----

    #[test]
    fn is_ready_partial_dependencies_not_met() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec![])
            .add_step("c", vec!["a".to_string(), "b".to_string()])
            .build()
            .unwrap();

        let mut completed = HashSet::new();
        completed.insert("a".to_string());

        // "b" is not completed yet, so "c" is not ready
        assert!(!graph.is_ready("c", &completed));
    }

    #[test]
    fn is_ready_all_dependencies_met() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec![])
            .add_step("c", vec!["a".to_string(), "b".to_string()])
            .build()
            .unwrap();

        let mut completed = HashSet::new();
        completed.insert("a".to_string());
        completed.insert("b".to_string());

        assert!(graph.is_ready("c", &completed));
    }

    // ---- compute_skips complex cases ----

    #[test]
    fn compute_skips_diamond_skips_root() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["a".to_string()])
            .add_step("d", vec!["b".to_string(), "c".to_string()])
            .build()
            .unwrap();

        let mut skip = HashSet::new();
        skip.insert("a".to_string());

        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
        assert_eq!(skipped.len(), 4);
    }

    #[test]
    fn compute_skips_leaf_only_skips_itself() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["b".to_string()])
            .build()
            .unwrap();

        let mut skip = HashSet::new();
        skip.insert("c".to_string());

        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
        assert_eq!(skipped.len(), 1);
        assert!(skipped.contains("c"));
    }

    #[test]
    fn compute_skips_multiple_roots() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .add_step("x", vec![])
            .add_step("y", vec!["x".to_string()])
            .build()
            .unwrap();

        let mut skip = HashSet::new();
        skip.insert("a".to_string());
        skip.insert("x".to_string());

        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
        assert_eq!(skipped.len(), 4);
    }

    // ---- Graph accessors ----

    #[test]
    fn steps_returns_all_step_names() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let steps = graph.steps();
        assert_eq!(steps.len(), 2);
        assert!(steps.contains("a"));
        assert!(steps.contains("b"));
    }

    #[test]
    fn len_matches_step_count() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .add_step("b", vec![])
            .add_step("c", vec![])
            .build()
            .unwrap();

        assert_eq!(graph.len(), 3);
        assert!(!graph.is_empty());
    }
}

